const fs = require('fs');
const DIR = '/home/user/ainews/storylines';
let applied = 0; const missed = [];
const variants = (s) => [...new Set([s, s.replace(/’/g, "'"), s.replace(/'/g, '’')])];

const fix = (id, reps) => {
  const f = `${DIR}/${id}.json`;
  const s = JSON.parse(fs.readFileSync(f, 'utf8'));
  const st = s.states[s.states.length - 1];
  for (const [a, b, tag] of reps) {
    let hit = false;
    for (const av of variants(a)) {
      for (let i = 0; i < st.text.length; i++) if (st.text[i].includes(av)) { st.text[i] = st.text[i].split(av).join(b); hit = true; }
      if (hit) break;
    }
    if (hit) applied++; else missed.push(`${id}: ${tag}`);
  }
  fs.writeFileSync(f, JSON.stringify(s, null, 2) + '\n');
};

