w=json.load(open('data/2026-10-05.week.json',encoding='utf-8'))
def walk(o,path=''):
    if isinstance(o,str):
        for pat in ['and and','that that']:
            if pat in o:
                i=o.find(pat)
                print(f'{path}: ...{o[max(0,i-90):i+90]}...')
    elif isinstance(o,list):
        for k,v in enumerate(o): walk(v,f'{path}[{k}]')
    elif isinstance(o,dict):
        for k,v in o.items(): walk(v,f'{path}.{k}')
walk(w)
PYEOF

